$(document).ready(function(a){function e(a){$.ajax({type:"POST",dataType:"json",data:{type:"booking",action:"availability"},success:function(e){var n=e.availablity;$(a).append("<h3>Select Date and Time<span>Choose a date below to place a request for pangat</span></h3>"),$.each(n,function(e,o){$(a).append("</div><div class='date-list' ><div class='date' >"+n[e].date+"</div><div class='bookPangat "+(1==n[e].breakfast?"green":0==n[e].breakfast?"red":"yellow")+"' >नाश्ता</div><div class='bookPangat "+(1==n[e].lunch?"green":0==n[e].lunch?"red":"yellow")+"' >दोपहर</div><div class='bookPangat "+(1==n[e].dinner?"green":0==n[e].dinner?"red":"yellow")+"' >रात्रि</div></div>")})},error:function(a){console.log("Error"+a)}})}$(".calender").is(":visible")?e(".calender"):console.log("Page is not load")});